package io.knowledgebrain.planning;
import java.time.*;import java.util.*;import java.security.MessageDigest;
import tools.jackson.databind.json.JsonMapper;
final class RecurrenceRules {
 record Input(String title,String description,String startsLocal,String endsLocal,String timeZone,UUID taskId,String frequency,int interval,int count,String startsOverlap,String endsOverlap){}
 record Occurrence(int ordinal,String startsAt,String endsAt,String startsLocal,String endsLocal,String startsOffset,String endsOffset){}
 record Issue(int ordinal,String field,String local,String reason,List<ScheduleRules.Option> options){}
 record Preview(UUID spaceId,Input input,List<Occurrence> occurrences,List<Issue> issues,String previewHash){}
 static void input(Input v){if(v==null)throw ScheduleRules.bad();GoalRules.input(new GoalStore.Input(v.title(),v.description(),"NOT_STARTED",null));ScheduleRules.local(v.startsLocal());ScheduleRules.local(v.endsLocal());ScheduleRules.zone(v.timeZone());if(v.taskId()!=null)ScheduleRules.id(v.taskId());if(v.frequency()==null||v.startsOverlap()==null||v.endsOverlap()==null||!Set.of("DAILY","WEEKLY").contains(v.frequency())||v.interval()<1||v.interval()>(v.frequency().equals("DAILY")?365:52)||v.count()<2||v.count()>100||!Set.of("REJECT","EARLIER","LATER").contains(v.startsOverlap())||!Set.of("REJECT","EARLIER","LATER").contains(v.endsOverlap()))throw ScheduleRules.bad();}
 static String hash(Object value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(JsonMapper.builder().build().writeValueAsBytes(value)));}catch(Exception e){throw new IllegalStateException(e);}}
 static void hash(String value){if(value==null||!value.matches("[0-9a-f]{64}"))throw ScheduleRules.bad();}
 private static ScheduleRules.Option resolve(UUID space,int ordinal,String field,LocalDateTime local,String zone,String choice,List<Issue> issues){String label=ScheduleRules.LOCAL.format(local);var options=ScheduleRules.options(space,label,zone).options();if(options.isEmpty()){issues.add(new Issue(ordinal,field,label,"GAP",options));return null;}if(options.size()>1&&choice.equals("REJECT")){issues.add(new Issue(ordinal,field,label,"OVERLAP",options));return null;}return options.get(choice.equals("LATER")?options.size()-1:0);}
 static Preview preview(UUID space,Input v){ScheduleRules.id(space);input(v);var rows=new ArrayList<Occurrence>();var issues=new ArrayList<Issue>();var first=ScheduleRules.local(v.startsLocal());var last=ScheduleRules.local(v.endsLocal());for(int n=0;n<v.count();n++){try{long days=(long)n*v.interval()*(v.frequency().equals("WEEKLY")?7:1);var a=first.plusDays(days);var z=last.plusDays(days);if(a.getYear()>9999||z.getYear()>9999)throw new DateTimeException("Year limit");var start=resolve(space,n+1,"startsLocal",a,v.timeZone(),v.startsOverlap(),issues);var end=resolve(space,n+1,"endsLocal",z,v.timeZone(),v.endsOverlap(),issues);if(start!=null&&end!=null){if(!ScheduleRules.instant(end.instant()).isAfter(ScheduleRules.instant(start.instant())))issues.add(new Issue(n+1,"interval",ScheduleRules.LOCAL.format(a),"NONPOSITIVE_INTERVAL",List.of()));else rows.add(new Occurrence(n+1,start.instant(),end.instant(),ScheduleRules.LOCAL.format(a),ScheduleRules.LOCAL.format(z),start.offset(),end.offset()));}}catch(DateTimeException|org.springframework.web.server.ResponseStatusException e){issues.add(new Issue(n+1,"interval","","OUT_OF_RANGE",List.of()));}}var result=new Preview(space,v,List.copyOf(rows),List.copyOf(issues),null);return new Preview(space,v,result.occurrences(),result.issues(),issues.isEmpty()?hash(result):null);}
}
